{
  "slug": "create-ticket",
  "name": "Create ticket",
  "description": "Creates a ticket in the core service",
  "node_type": "serviceCall",
  "config": {
    "method": "POST",
    "serviceSlug": "core",
    "path": "/api/v1/tickets",
    "rawBody": {
      "id": "{{ params.ticketId }}",
      "priority": "{{ params.priority }}"
    }
  },
  "params": {
    "ticketId": {
      "required": true,
      "label": "Ticket id"
    },
    "priority": {
      "default": "low"
    }
  }
}

